using SimplePZMapmaker.Web.Services;
using SimplePZMapmaker.Core;
using System.Net;
public static class UpstreamTests
{
    public static IEnumerable<(string,Action)> Cases(){foreach(var lengthKnown in new[]{false,true})yield return ($"OSM download bounded before buffering (Content-Length={lengthKnown})",()=>{
        var stream=new ProbeStream();var directory=Path.Combine(Directory.GetCurrentDirectory(),"work","upstream-tests",Guid.NewGuid().ToString("N"));
        using var client=new OsmClient(directory,new FakeHandler(stream,lengthKnown));
        try{client.Fetch(new(){West=30,East=30.001,South=50,North=50.001},CancellationToken.None).GetAwaiter().GetResult();throw new Exception("Oversized response accepted");}
        catch(ArgumentException){if(stream.ReadBytes>16_008_192)throw new Exception($"Buffered {stream.ReadBytes} bytes before limit");}
    });
    yield return ("OSM falls back after 504 and caches complete response",()=>{
        var directory=Path.Combine(Directory.GetCurrentDirectory(),"work","upstream-tests",Guid.NewGuid().ToString("N"));var handler=new SequenceHandler([new(HttpStatusCode.GatewayTimeout),new(HttpStatusCode.OK){Content=new StringContent("{\"elements\":[]}")}]);using var client=new OsmClient(directory,handler,TimeSpan.Zero);var bounds=new GeoBounds{West=30,East=30.001,South=50,North=50.001};var result=client.FetchDetailed(bounds,CancellationToken.None).GetAwaiter().GetResult();if(handler.Calls!=2||result.Warnings.Count==0||!result.Source.Contains("private.coffee"))throw new Exception("No sequential provider fallback");client.Fetch(bounds,CancellationToken.None).GetAwaiter().GetResult();if(handler.Calls!=2)throw new Exception("Complete response was not cached");
    });
    yield return ("OSM discards partial timeout results and preserves cancellation",()=>{
        var directory=Path.Combine(Directory.GetCurrentDirectory(),"work","upstream-tests",Guid.NewGuid().ToString("N"));var handler=new SequenceHandler([new(HttpStatusCode.OK){Content=new StringContent("{\"remark\":\"runtime error: Query timed out\",\"elements\":[]}")},new(HttpStatusCode.OK){Content=new StringContent("{\"elements\":[]}")}]);using var client=new OsmClient(directory,handler,TimeSpan.Zero);client.Fetch(new(){West=30,East=30.001,South=50,North=50.001},CancellationToken.None).GetAwaiter().GetResult();if(handler.Calls!=2)throw new Exception("Partial OSM data accepted");using var cancel=new CancellationTokenSource();cancel.Cancel();try{client.Fetch(new(){West=31,East=31.001,South=50,North=50.001},cancel.Token).GetAwaiter().GetResult();}catch(OperationCanceledException){if(handler.Calls==2)return;}throw new Exception("Cancelled import contacted another server");
    });
    yield return ("regional extract refuses other cities before network",()=>{
        var handler=new SequenceHandler([]);using var client=new OsmClient(TestDirectory(),handler,TimeSpan.Zero);try{client.FetchExtractDetailed(new(){South=50,North=50.001,West=30,East=30.001},CancellationToken.None).GetAwaiter().GetResult();}catch(ArgumentException){if(handler.Calls==0)return;}throw new Exception("Unsupported extract contacted network");
    });
    foreach(var compressed in new[]{false,true})yield return ($"PBF regional clip retains complete dense-node rings (zlib={compressed})",()=>{
        var path=Path.Combine(TestDirectory(),"fixture.pbf");File.WriteAllBytes(path,PbfFixture(compressed));var result=PbfExtractReader.Read(path,ExtractBounds());using var json=System.Text.Json.JsonDocument.Parse(result.Data);var way=json.RootElement.GetProperty("elements")[0];var geometry=way.GetProperty("geometry");if(way.GetProperty("id").GetInt64()!=77||geometry.GetArrayLength()!=5||geometry[1].GetProperty("lat").GetDouble()<54.787||geometry[0].ToString()!=geometry[4].ToString()||way.GetProperty("tags").GetProperty("name").GetString()!="Живой дом")throw new Exception("PBF clipping truncated or changed the way");if(result.OmittedRelations!=0||result.Timestamp is null)throw new Exception("Extract metadata lost");
    });
    yield return ("PBF incomplete relation is omitted whole and reported",()=>{
        var path=Path.Combine(TestDirectory(),"fixture.pbf");File.WriteAllBytes(path,PbfFixture(false,true));var result=PbfExtractReader.Read(path,ExtractBounds());using var json=System.Text.Json.JsonDocument.Parse(result.Data);if(result.OmittedRelations!=1||json.RootElement.GetProperty("elements").EnumerateArray().Any(e=>e.GetProperty("type").GetString()=="relation"))throw new Exception("Incomplete water contour masquerades as complete");
    });
    yield return ("regional download caches a complete snapshot and rejects malformed downloads atomically",()=>{
        var directory=TestDirectory();var handler=new SequenceHandler([new(HttpStatusCode.OK){Content=new ByteArrayContent(PbfFixture(true))}]);using var client=new OsmClient(directory,handler);var first=client.FetchExtractDetailed(ExtractBounds(),CancellationToken.None).GetAwaiter().GetResult();var second=client.FetchExtractDetailed(ExtractBounds(),CancellationToken.None).GetAwaiter().GetResult();if(handler.Calls!=1||first.Source!="download.openstreetmap.fr"||!second.Warnings.Any(w=>w.Contains("кэш"))||first.Data!=second.Data)throw new Exception("Snapshot cache incomplete or repeated network");
        var broken=TestDirectory();using var bad=new OsmClient(broken,new SequenceHandler([new(HttpStatusCode.OK){Content=new ByteArrayContent([0,0,0,32,1])}]));try{bad.FetchExtractDetailed(ExtractBounds(),CancellationToken.None).GetAwaiter().GetResult();}catch(ArgumentException){if(Directory.GetFiles(broken).Length==0)return;}throw new Exception("Malformed snapshot became stable cache");
    });
    yield return ("regional download enforces byte limit and cleans cancellation",()=>{
        var directory=TestDirectory();var stream=new ProbeStream();var content=new StreamContent(stream);content.Headers.ContentLength=70_000_000;using var client=new OsmClient(directory,new SequenceHandler([new(HttpStatusCode.OK){Content=content}]));try{client.FetchExtractDetailed(ExtractBounds(),CancellationToken.None).GetAwaiter().GetResult();}catch(ArgumentException){if(stream.ReadBytes!=0||Directory.GetFiles(directory).Length!=0)throw new Exception("Oversized snapshot buffered or cached");}
        using var cancel=new CancellationTokenSource();var cancelled=TestDirectory();using var abort=new OsmClient(cancelled,new CancellingHandler(cancel));try{abort.FetchExtractDetailed(ExtractBounds(),cancel.Token).GetAwaiter().GetResult();}catch(OperationCanceledException){if(Directory.GetFiles(cancelled).Length==0)return;}throw new Exception("Cancelled snapshot became cache");
    });
    yield return ("PBF malformed headers and decompression declarations reject safely",()=>{
        foreach(var bytes in new[]{Array.Empty<byte>(),new byte[]{0,0,0,32,1},new byte[]{127,255,255,255},PbfFixture(true)[..^4]}){var path=Path.Combine(TestDirectory(),"bad.pbf");File.WriteAllBytes(path,bytes);try{PbfExtractReader.Read(path,ExtractBounds());}catch(ArgumentException){continue;}throw new Exception("Malformed PBF accepted");}
    });
    yield return ("PBF crossing segment and enclosing polygon survive without inside vertices",()=>{
        foreach(var mode in new[]{"road","polygon"}){var path=Path.Combine(TestDirectory(),"crossing.pbf");File.WriteAllBytes(path,PbfFixture(false,false,mode));var result=PbfExtractReader.Read(path,InteriorBounds());using var json=System.Text.Json.JsonDocument.Parse(result.Data);var elements=json.RootElement.GetProperty("elements");if(elements.GetArrayLength()!=1||elements[0].GetProperty("id").GetInt64()!=77)throw new Exception("Intersecting geometry disappeared without an in-box vertex");if(elements[0].GetProperty("geometry").GetArrayLength()!=(mode=="road"?2:5))throw new Exception("Clipping truncated complete geometry");}
        var original=Path.Combine(TestDirectory(),"triangle.pbf");File.WriteAllBytes(original,PbfFixture(false));var triangle=PbfExtractReader.Read(original,InteriorBounds());var map=GeographicImporter.Import(triangle.Data,MapGenerator.Generate(new(){Kind="blank"}),InteriorBounds()).Project;if(map.Terrain.Count(t=>t==Terrain.Water)!=50289)throw new Exception("Complete water triangle raster differs from source geometry");
    });
    yield return ("PBF enclosing relations keep all outer members and respect inner holes",()=>{
        var path=Path.Combine(TestDirectory(),"hole.pbf");File.WriteAllBytes(path,PbfFixture(false,false,"hole"));var hole=PbfExtractReader.Read(path,InteriorBounds());using(var json=System.Text.Json.JsonDocument.Parse(hole.Data))if(json.RootElement.GetProperty("elements").GetArrayLength()!=0||hole.OmittedRelations!=0)throw new Exception("Inside-hole bbox became a filled outer polygon");
        var belowHole=new GeoBounds{South=54.776,North=54.778,West=32.050,East=32.052};var wet=PbfExtractReader.Read(path,belowHole);using(var json=System.Text.Json.JsonDocument.Parse(wet.Data)){var e=json.RootElement.GetProperty("elements");if(e.GetArrayLength()!=1||e[0].GetProperty("type").GetString()!="relation"||e[0].GetProperty("members").GetArrayLength()!=2)throw new Exception("Containing relation lost outside outer/inner geometry");}
        File.WriteAllBytes(path,PbfFixture(true,false,"split"));var split=PbfExtractReader.Read(path,InteriorBounds());using(var json=System.Text.Json.JsonDocument.Parse(split.Data)){var e=json.RootElement.GetProperty("elements");if(e.GetArrayLength()!=1||e[0].GetProperty("members").GetArrayLength()!=2)throw new Exception("Open outer member segments failed to stitch around bbox");}
    });
    yield return ("PBF full-region indexes fail explicitly on budgets missing nodes and cancellation",()=>{
        var path=Path.Combine(TestDirectory(),"budget.pbf");File.WriteAllBytes(path,PbfFixture(false));foreach(var budget in new[]{new PbfExtractReader.Budgets(Nodes:2),new PbfExtractReader.Budgets(Ways:1),new PbfExtractReader.Budgets(References:4),new PbfExtractReader.Budgets(GeometryWork:1)}){try{PbfExtractReader.Read(path,InteriorBounds(),default,budget);}catch(ArgumentException){continue;}throw new Exception("Regional index budget silently exceeded");}
        File.WriteAllBytes(path,PbfFixture(false,false,"missing"));var incomplete=PbfExtractReader.Read(path,InteriorBounds());using(var json=System.Text.Json.JsonDocument.Parse(incomplete.Data))if(incomplete.OmittedWays!=1||json.RootElement.GetProperty("elements").GetArrayLength()!=0)throw new Exception("Missing geometry nodes became a partial object without explicit report");
        using var cancelled=new CancellationTokenSource();cancelled.Cancel();try{PbfExtractReader.Read(path,InteriorBounds(),cancelled.Token);}catch(OperationCanceledException){return;}throw new Exception("Cancelled geometry work continued");
    });}
    private static string TestDirectory(){var path=Path.Combine(Directory.GetCurrentDirectory(),"work","upstream-tests",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(path);return path;}
    private static GeoBounds ExtractBounds()=>new(){South=54.777,North=54.779,West=32.046,East=32.049};
    private static GeoBounds InteriorBounds()=>new(){South=54.782,North=54.784,West=32.050,East=32.052};
    private sealed class CancellingHandler(CancellationTokenSource cancel):HttpMessageHandler{protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){cancel.Cancel();return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(PbfFixture(false))});}}
    private static byte[] PbfFixture(bool compressed,bool incomplete=false,string mode="original"){
        static byte[] Var(ulong value){var bytes=new List<byte>();do{var b=(byte)(value&127);value>>=7;bytes.Add((byte)(b|(value>0?128:0)));}while(value>0);return bytes.ToArray();}
        static byte[] Join(params byte[][] values)=>values.SelectMany(v=>v).ToArray();
        static byte[] Int(int field,long value)=>Join(Var((ulong)field<<3),Var(unchecked((ulong)value)));
        static byte[] Bytes(int field,byte[] value)=>Join(Var(((ulong)field<<3)|2),Var((ulong)value.Length),value);
        static byte[] Text(int field,string value)=>Bytes(field,System.Text.Encoding.UTF8.GetBytes(value));
        static byte[] Pack(int field,long[] values,bool signed=false)=>Bytes(field,Join(values.Select(v=>Var(signed?unchecked((ulong)((v<<1)^(v>>63))):unchecked((ulong)v))).ToArray()));
        byte[] Frame(string type,byte[] raw){byte[] blob;if(compressed){using var packed=new MemoryStream();using(var z=new System.IO.Compression.ZLibStream(packed,System.IO.Compression.CompressionMode.Compress,true))z.Write(raw);blob=Join(Int(2,raw.Length),Bytes(3,packed.ToArray()));}else blob=Bytes(1,raw);var header=Join(Text(1,type),Int(3,blob.Length));var size=new byte[4];System.Buffers.Binary.BinaryPrimitives.WriteInt32BigEndian(size,header.Length);return Join(size,header,blob);}
        var header=Join(Text(4,"OsmSchema-V0.6"),Text(4,"DenseNodes"),Int(32,1791678545));var strings=new[]{"",mode=="road"?"highway":mode is "polygon" or "hole"?"natural":"building",mode=="road"?"residential":mode is "polygon" or "hole"?"water":"yes","name","Живой дом","natural","water","type","multipolygon","outer","inner"};var table=Join(strings.Select(v=>Text(1,v)).ToArray());
        long[] lat=mode=="road"?[547830000,547830000]:mode is "polygon" or "hole" or "split"?[547700000,547950000,547950000,547700000]:[547780000,547880000,547880000,547780000];long[] lon=mode=="road"?[320470000,320570000]:mode is "polygon" or "hole" or "split"?[320400000,320400000,320650000,320650000]:[320470000,320470000,320570000,320470000];if(mode=="hole"){lat=[..lat,547810000,547850000,547850000,547810000];lon=[..lon,320490000,320490000,320550000,320550000];}if(mode=="missing"){lat=lat[..3];lon=lon[..3];}
        static long[] Delta(long[] values){long previous=0;return values.Select(v=>{var d=v-previous;previous=v;return d;}).ToArray();}
        var dense=Join(Pack(1,Delta(Enumerable.Range(100,lat.Length).Select(i=>(long)i).ToArray()),true),Pack(8,Delta(lat),true),Pack(9,Delta(lon),true));var primaryRefs=mode=="road"?new long[]{100,101}:mode=="split"?[100,101,102]:new long[]{100,101,102,103,100};var tags=mode=="split"?Array.Empty<byte>():Join(Pack(2,[1,3]),Pack(3,[2,4]));var way=Join(Int(1,77),tags,Pack(8,Delta(primaryRefs),true));var waterRefs=mode=="hole"?new long[]{104,105,106,107,104}:mode=="split"?[102,103,100]:new long[]{100,101,102,103,100};var water=Join(Int(1,88),Pack(8,Delta(waterRefs),true));var members=mode is "hole" or "split"?new long[]{77,88}:incomplete?[88,999]:new long[]{88};var roles=mode=="hole"?new long[]{9,10}:members.Select(_=>9L).ToArray();var relation=Join(Int(1,9),Pack(2,[5,7]),Pack(3,[6,8]),Pack(8,roles),Pack(9,Delta(members),true),Pack(10,members.Select(_=>1L).ToArray()));
        var group=mode is "road" or "polygon" or "missing"?Join(Bytes(2,dense),Bytes(3,way)):Join(Bytes(2,dense),Bytes(3,way),Bytes(3,water),Bytes(4,relation));var block=Join(Bytes(1,table),Bytes(2,group));return Join(Frame("OSMHeader",header),Frame("OSMData",block));
    }
    private sealed class SequenceHandler(HttpResponseMessage[] responses):HttpMessageHandler{public int Calls;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){token.ThrowIfCancellationRequested();return Task.FromResult(responses[Calls++]);}}
    private sealed class FakeHandler(ProbeStream stream,bool lengthKnown):HttpMessageHandler {
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){var content=new StreamContent(stream);if(lengthKnown)content.Headers.ContentLength=20_000_000;return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=content});}
    }
    private sealed class ProbeStream:Stream {
        public long ReadBytes {get;private set;}
        public override int Read(byte[] buffer,int offset,int count){var n=(int)Math.Min(count,20_000_000-ReadBytes);Array.Fill(buffer,(byte)' ',offset,n);ReadBytes+=n;return n;}
        public override bool CanRead=>true;public override bool CanSeek=>false;public override bool CanWrite=>false;public override long Length=>20_000_000;
        public override long Position {get=>ReadBytes;set=>throw new NotSupportedException();}
        public override void Flush(){}public override long Seek(long offset,SeekOrigin origin)=>throw new NotSupportedException();public override void SetLength(long value)=>throw new NotSupportedException();public override void Write(byte[] buffer,int offset,int count)=>throw new NotSupportedException();
    }
}
